SELECT AVG(dragons) AS media_dragoes_por_partida
FROM pro_games
WHERE year = 2026;

SELECT COUNT(DISTINCT game_id) AS partidas_sem_barao
FROM pro_games
WHERE barons = 0;

SELECT AVG(towers) AS media_torres_vencedoras
FROM pro_games
WHERE win = true;

SELECT AVG(pg.barons) AS media_barons_vencedoras
FROM pro_games pg
WHERE pg.win = true;
